-- Aliman Merchandise: manual phpMyAdmin import
-- Create and select a NEW EMPTY database named aliman_merchandise_final.
-- Import this file ONCE. No existing database is dropped.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS users (id INT PRIMARY KEY AUTO_INCREMENT,name TEXT NOT NULL,email VARCHAR(191) NOT NULL UNIQUE,password_hash TEXT NOT NULL,google_sub VARCHAR(191) UNIQUE,role VARCHAR(20) NOT NULL DEFAULT 'customer' CHECK(role IN ('owner','employee','customer')),active INT NOT NULL DEFAULT 1,must_change_password INT NOT NULL DEFAULT 0,created_at VARCHAR(19) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS categories (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(191) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id INT PRIMARY KEY AUTO_INCREMENT,sku VARCHAR(191) NOT NULL UNIQUE,name TEXT NOT NULL,brand VARCHAR(80) NOT NULL DEFAULT '',category_id INT NOT NULL,description VARCHAR(2000) NOT NULL DEFAULT '',price_cents BIGINT NOT NULL CHECK(price_cents>=0),stock INT NOT NULL DEFAULT 0 CHECK(stock>=0),low_stock INT NOT NULL DEFAULT 10,image_url VARCHAR(500) NOT NULL DEFAULT '',active INT NOT NULL DEFAULT 1,deleted INT NOT NULL DEFAULT 0,version INT NOT NULL DEFAULT 1,created_at VARCHAR(19) NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY (category_id) REFERENCES categories(id),INDEX idx_products_category(category_id,active,deleted)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cart_items (user_id INT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL CHECK(quantity>0),PRIMARY KEY(user_id,product_id),FOREIGN KEY (user_id) REFERENCES users(id),FOREIGN KEY (product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id INT PRIMARY KEY AUTO_INCREMENT,reference VARCHAR(191) NOT NULL UNIQUE,user_id INT NOT NULL,email VARCHAR(191) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','ready','completed','cancelled')),total_cents BIGINT NOT NULL CHECK(total_cents>=0),payment_method VARCHAR(20) NOT NULL DEFAULT 'cash',payment_status VARCHAR(24) NOT NULL DEFAULT 'unpaid',paypal_order_id VARCHAR(100) UNIQUE,paymongo_session_id VARCHAR(100) UNIQUE,paymongo_payment_id VARCHAR(100) UNIQUE,paymongo_livemode INT NOT NULL DEFAULT 0,paymongo_expired INT NOT NULL DEFAULT 0,payment_lock INT NOT NULL DEFAULT 0,pickup_date TEXT NOT NULL,notes VARCHAR(500) NOT NULL DEFAULT '',claim_code VARCHAR(191) NOT NULL UNIQUE,idempotency_key VARCHAR(191) NOT NULL,created_at VARCHAR(19) NOT NULL,updated_at TEXT NOT NULL,paid_at TEXT,UNIQUE(user_id,idempotency_key),FOREIGN KEY (user_id) REFERENCES users(id),INDEX idx_orders_user(user_id,created_at),INDEX idx_orders_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items (id INT PRIMARY KEY AUTO_INCREMENT,order_id INT NOT NULL,product_id INT NOT NULL,name TEXT NOT NULL,sku VARCHAR(191) NOT NULL,price_cents BIGINT NOT NULL,quantity INT NOT NULL CHECK(quantity>0),FOREIGN KEY (order_id) REFERENCES orders(id),FOREIGN KEY (product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS activity (id INT PRIMARY KEY AUTO_INCREMENT,user_id INT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL,created_at VARCHAR(19) NOT NULL,FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (name VARCHAR(191) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS api_cache (id VARCHAR(191) PRIMARY KEY,provider TEXT NOT NULL,body LONGTEXT NOT NULL,mime TEXT NOT NULL,expires INT NOT NULL,created_at VARCHAR(19) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS api_events (provider VARCHAR(191) PRIMARY KEY,status VARCHAR(24) NOT NULL,message TEXT NOT NULL,checked_at TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rate_limits (id VARCHAR(191) PRIMARY KEY,hits INT NOT NULL,expires INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS email_outbox (id INT PRIMARY KEY AUTO_INCREMENT,order_id INT NOT NULL,event VARCHAR(40) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'pending',attempts INT NOT NULL DEFAULT 0,last_error VARCHAR(250) NOT NULL DEFAULT '',created_at VARCHAR(19) NOT NULL,sent_at TEXT,UNIQUE(order_id,event),FOREIGN KEY (order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

